{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    payload = case.get("payload")
    if not isinstance(payload, dict):
        raise ValueError("payload missing or invalid")
    threshold = payload.get("threshold")
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be a number")
    calls = payload.get("calls")
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")
    results = []
    for call in calls:
        if not isinstance(call, dict):
            raise ValueError("each call must be a dict")
        call_id = call.get("call_id")
        loss_without = call.get("loss_without_call")
        loss_with = call.get("loss_with_call")
        pred_tokens = call.get("prediction_tokens")
        parseable = call.get("parseable")
        if any(x is None for x in [call_id, loss_without, loss_with, pred_tokens, parseable]):
            raise ValueError("missing required field in call")
        if not isinstance(call_id, str):
            raise ValueError("call_id must be string")
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be bool")
        if not isinstance(pred_tokens, int) or pred_tokens < 1:
            raise ValueError("prediction_tokens must be positive integer")
        gain = loss_without - loss_with
        normalized_gain = gain / pred_tokens
        results.append({
            "call_id": call_id,
            "normalized_gain": normalized_gain,
            "parseable": parseable
        })
    accepted = [r for r in results if r["parseable"] and r["normalized_gain"] >= threshold]
    accepted_call_ids = [r["call_id"] for r in accepted]
    diagnostics = [round(r["normalized_gain"], 6) for r in accepted]
    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics
    }
"}
